sys_script_include.script:
var Constants = (function () {

    var SCOPE = 'x_gegis_ins_policy';

    // ---------------------------------------------------------------------
    // System property names - the ONLY place these strings are written.
    // ---------------------------------------------------------------------
    var PROP = {
        // Auto-approve extraction payloads per pipeline intent.
        // true  = auto-accept extracted fields + auto-close the HITL task
        // false = leave fields needs_review + keep the HITL task open
        AUTO_APPROVE_NEW:    SCOPE + '.extraction.auto_approve.new',
        AUTO_APPROVE_UPDATE: SCOPE + '.extraction.auto_approve.update',

        // License + staged execution plan (JSON) for module orchestration:
        // clearance, exposure, risk, quote & bind.
        MODULE_EXECUTION_CONFIG: SCOPE + '.module_execution_config'
    };

    // Fail-safe defaults, mirrored from the property defaults.
    var DEFAULT = {};
    DEFAULT[PROP.AUTO_APPROVE_NEW]    = 'true';
    DEFAULT[PROP.AUTO_APPROVE_UPDATE] = 'false';

    // =====================================================================
    // CUSTOM CHOICE VALUES  --  GOLDEN RULE
    // ---------------------------------------------------------------------
    // Every custom choice value in Policy Suite is a lower_snake_case string
    // and lives here as a named constant. Scripts, flows and business rules
    // reference x_gegis_ins_policy.Constants.CHOICE.* -- never a raw string
    // literal. Labels stay in the instance UI (choices are configured there,
    // not generated); this catalog is the source of truth for the VALUES.
    //
    // Same value used in more than one place:
    //   1. Same LABEL, different meaning per context  -> give each its own
    //      value, namespaced by its stage prefix (e.g. "Extract" becomes
    //      ACTIVITY.CLEARANCE.EXTRACT = 'clearance_extract' vs
    //      ACTIVITY.EXPOSURE.EXTRACT = 'exposure_extract'). Values stay unique.
    //   2. Same VALUE legitimately shared across fields (e.g. 'declined',
    //      'cancelled', 'closed' on both state and status) -> define the token
    //      ONCE in SHARED and reference it. Never re-type the literal.
    // =====================================================================

    // Value tokens that appear on more than one field. Defined once here.
    var SHARED = {
        NEW:         'new',
        IN_PROGRESS: 'in_progress',
        ON_HOLD:     'on_hold',
        // shared by extraction.extraction_status and the case tables' u_status
        PENDING:     'pending',
        DUPLICATE:   'duplicate',
        REJECTED:    'rejected',
        FAILED:      'failed',
        EXTRACTED:   'extracted',
        APPLIED:     'applied',
        // shared by extraction.source and case_task.category
        CASE:        'case',
        // shared by case_task.category and case_task.u_type -- a referral is
        // both a category of task and a kind of hand-off
        REFERRAL:    'referral',
        DECLINED:    'declined',
        CANCELLED:   'cancelled',
        CLOSED:      'closed',
        // shared by case_task.category and party.verification_source
        OTHER:       'other',
        // renewal decision tokens - shared by uw_decision + system_decision
        FULL_RE_UNDERWRITING: 'full_re_underwriting',
        AUTO_RENEW:           'auto_renew',
        DO_NOT_RENEW:         'do_not_renew',
        // shared by party.status and policy.status
        ACTIVE:      'active',
        // shared by submission.status and policy.status
        BOUND:       'bound',
        // shared by policy.status and quote.status
        EXPIRED:     'expired',
        // shared by submission.status and quote.status
        DRAFT:       'draft',
        // shared by extraction.extraction_status and quote.status
        ACCEPTED:    'accepted',
        // shared by quote.status and bind.status -- the quote is issued to the
        // broker, the bound policy is issued to the insured
        ISSUED:      'issued',
        // ---- product catalog / rating tokens that span more than one column ----
        // coverage.coverage_selection, major_exclusion.choice_value,
        // exposure_peril.expiring_status
        EXCLUDED:       'excluded',
        // major_exclusion.choice_value and exposure_peril.expiring_status
        INCLUDED:       'included',
        // coverage_term.term_type and policy_coverage_term.term_type
        LIMIT:          'limit',
        DEDUCTIBLE:     'deductible',
        // coverage.deductible_type, coverage_term.term_type,
        // coverage_term.data_type, rate_table.rate_type
        PERCENTAGE:     'percentage',
        // coverage.deductible_type and rate_table.rate_type
        FLAT:           'flat',
        // coverage.deductible_type and coverage.limit_type
        PER_OCCURRENCE: 'per_occurrence',
        PER_LOCATION:   'per_location',
        // coverage.deductible_type and policy_coverage_term.term_type
        WAITING_PERIOD: 'waiting_period',
        // coverage_term.term_type and coverage_term.data_type
        DURATION:       'duration',
        // rate_table_entry.zone and rate_table_entry.engine_cc -- WILDCARD, not a
        // real zone or band: the rate applies regardless of that dimension
        ANY:            'any',
        // rate_table_entry.vehicle_type and vehicle.vehicle_use
        COMMERCIAL:     'commercial',
        // ---- LOA tokens that span more than one column ----------------------
        // loa_authority_limit.class_of_business and .business_type -- WILDCARD,
        // meaning the limit applies regardless of that dimension. Distinct from
        // ANY above only by which columns carry it; same intent.
        ALL:            'all',
        // submission.submission_type and loa_authority_limit.business_type
        NEW_BUSINESS:   'new_business',
        RENEWAL:        'renewal',
        // loa_authority_grant.state and loa_authority_limit versioning language
        SUPERSEDED:     'superseded',
        REVOKED:        'revoked',
        // loa_metric.comparison and loa_metric.aggregation -- "the largest value"
        // in one case, "breach above the limit" in the other. Same token, and the
        // column it sits on says which question is being asked.
        MAX:            'max',
        // loa_metric.value_type and loa_metric.aggregation
        COUNT:          'count',
        // loa_metric.aggregation -- read the source field directly, do not roll up
        NONE:           'none'
    };

    // submission.stage -- also the prefix namespace for activity_status values.
    var STAGE = {
        CLEARANCE:           'clearance',
        RISK_ASSESSMENT:     'risk_assessment',
        EXPOSURE_MANAGEMENT: 'exposure_management',
        QUOTE_AND_BIND:      'quote_and_bind'
    };

    // activity_status, grouped per stage. Each token defined ONCE here.
    // A case table's activity_status = its own group. The submission's
    // activity_status = the union of all four (see CHOICE.ACTIVITY.all()).
    var ACTIVITY = {
        CLEARANCE: {
            INITIATE_SUBMISSION_REQUEST: 'clearance_initiate_submission_request',
            EXTRACT:                     'clearance_extract',
            INSURED_VERIFICATION:        'clearance_insured_verification',
            CHECK_FOR_DUPLICATES:        'clearance_check_for_duplicates',
            CHECK_FOR_SANCTIONS:         'clearance_check_for_sanctions',
            CONFIRM_DATA_REVIEW:         'clearance_confirm_data_review',
            QUALITY_ASSURANCE:           'clearance_quality_assurance'
        },
        RISK: {
            INITIATE_RISK_ASSESSMENT: 'risk_initiate_risk_assessment',
            LETTER_OF_AUTHORITY:      'risk_letter_of_authority',
            UNDERWRITING_GUIDELINES:  'risk_underwriting_guidelines',
            BENCHMARKING:             'risk_benchmarking',
            SURVEY_RESULTS:           'risk_survey_results',
            LOSS_PREDICTION:          'risk_loss_prediction',
            BIND_PROPENSITY:          'risk_bind_propensity',
            EXPOSURE_DATA:            'risk_exposure_data',
            FRAUD_DETECTION:          'risk_fraud_detection',
            UNDERWRITER_NARRATIVE:    'risk_underwriter_narrative',
            RISK_SUMMARY:             'risk_risk_summary'
        },
        EXPOSURE: {
            INITIATE_EXPOSURE:          'exposure_initiate_exposure',
            EXTRACT:                    'exposure_extract',
            GEO_MAPPING:                'exposure_geo_mapping',
            CATASTROPHE_MODELLING:      'exposure_catastrophe_modelling',
            CAPACITY_MANAGEMENT:        'exposure_capacity_management',
            CONCENTRATION_ANALYSIS:     'exposure_concentration_analysis',
            PORTFOLIO_OPTIMIZATION:     'exposure_portfolio_optimization',
            EXPOSURE_MANAGEMENT_SUMMARY:'exposure_management_summary'
        },
        QUOTEBIND: {
            INITIATE_QUOTE_AND_BIND:   'quotebind_initiate_quote_and_bind',
            EXTRACT:                   'quotebind_extract',
            PRODUCT_SELECTION_DETAILS: 'quotebind_product_selection_details',
            QUOTE_WORKSPACE:           'quotebind_quote_workspace',
            UNDERWRITER_DECISION:      'quotebind_underwriter_decision',
            BROKER_DECISION:           'quotebind_broker_decision',
            SANCTIONS:                 'quotebind_sanctions',
            BIND_DETAILS:              'quotebind_bind_details'
        }
    };

    // Union of all activity_status values, in stage order (submission set).
    ACTIVITY.all = function () {
        return values(ACTIVITY.CLEARANCE)
            .concat(values(ACTIVITY.RISK))
            .concat(values(ACTIVITY.EXPOSURE))
            .concat(values(ACTIVITY.QUOTEBIND));
    };

    var CHOICE = {
        STAGE:    STAGE,
        ACTIVITY: ACTIVITY,

        PRIORITY: {
            CRITICAL: 'critical',
            HIGH:     'high',
            MEDIUM:   'medium',
            LOW:      'low'
        },

        // x_gegis_ins_policy_case_task.category -- what kind of task this is.
        // Listed in the instance's choice sequence order (10/15/20/25/30).
        CATEGORY: {
            HITL:       'hitl',
            EXTRACTION: 'extraction',
            REFERRAL:   SHARED.REFERRAL,
            CASE:       SHARED.CASE,
            OTHER:      SHARED.OTHER
        },

        // x_gegis_ins_policy_case_task.u_type -- WHY the task exists, i.e. the
        // trigger that raised it. Orthogonal to CATEGORY, which is what kind of
        // task it is. Listed in the instance's choice sequence order
        // (10/20/30/40/50/60).
        U_TYPE: {
            CONTEXT_ENRICHMENT:    'context_enrichment',
            DUPLICATE_CHECK:       'duplicate_check',
            CLASSIFICATION_FAILED: 'classification_failed',
            SUBMISSION_LOCKED:     'submission_locked',
            EXTRACTION_REVIEW:     'extraction_review',
            REFERRAL:              SHARED.REFERRAL
        },

        // submission.state
        STATE: {
            NEW:         SHARED.NEW,
            IN_PROGRESS: SHARED.IN_PROGRESS,
            ON_HOLD:     SHARED.ON_HOLD,
            DECLINED:    SHARED.DECLINED,
            CLOSED:      SHARED.CLOSED,
            CANCELLED:   SHARED.CANCELLED
        },

        // submission.status  (shares declined/cancelled/closed with STATE)
        STATUS: {
            DRAFT:            SHARED.DRAFT,
            UNDER_REVIEW:     'under_review',
            PENDING_APPROVAL: 'pending_approval',
            MISSING_DATA:     'missing_data',
            APPROVED:         'approved',
            DECLINED:         SHARED.DECLINED,
            REJECTED:         SHARED.REJECTED,
            DUPLICATE:        SHARED.DUPLICATE,
            RENEWAL_DUE:      'renewal_due',
            RENEWED:          'renewed',
            BOUND:            SHARED.BOUND,
            CANCELLED:        SHARED.CANCELLED,
            CLOSED:           SHARED.CLOSED
        },

        // x_gegis_ins_policy_policy.status -- lifecycle of the POLICY CONTRACT,
        // not of the submission that produced it. bound = paperwork done,
        // in_force = cover actually running, non_renewed = allowed to lapse at
        // expiry (distinct from cancelled, which ends it mid-term).
        POLICY_STATUS: {
            ACTIVE:      SHARED.ACTIVE,
            BOUND:       SHARED.BOUND,
            IN_FORCE:    'in_force',
            CANCELLED:   SHARED.CANCELLED,
            EXPIRED:     SHARED.EXPIRED,
            NON_RENEWED: 'non_renewed'
        },

        // x_gegis_ins_policy_quote.status -- lifecycle of the quote document.
        // issued = sent to the broker; accepted/declined are the broker's answer.
        QUOTE_STATUS: {
            DRAFT:    SHARED.DRAFT,
            ISSUED:   SHARED.ISSUED,
            ACCEPTED: SHARED.ACCEPTED,
            DECLINED: SHARED.DECLINED,
            EXPIRED:  SHARED.EXPIRED
        },

        // x_gegis_ins_policy_bind.status -- what happened to the BIND, not to
        // the quote. bound = risk accepted and on cover; issued = the policy
        // document has gone out; cancelled = bound then unwound (flat cancel or
        // cancelled mid-term). The sys_choice rows for these three already exist
        // on the instance and are exported with the app; this group is the
        // catalogue entry that was missing, so scripts stop needing literals.
        BIND_STATUS: {
            BOUND:     SHARED.BOUND,
            ISSUED:    SHARED.ISSUED,
            CANCELLED: SHARED.CANCELLED
        },

        // x_gegis_ins_policy_intake_case.status
        INTAKE_STATUS: {
            NEW:             SHARED.NEW,
            IN_PROGRESS:     SHARED.IN_PROGRESS,
            AWAITING_ACTION: 'awaiting_action',
            COMPLETED:       'completed',
            DUPLICATE:       SHARED.DUPLICATE,
            REJECTED:        SHARED.REJECTED,
            CANCELLED:       SHARED.CANCELLED,
            FAILED:          SHARED.FAILED,
            READY_TO_SEND:   'ready_to_send',
            SENT:            'sent',
            ACKNOWLEDGED:    'acknowledged'
        },

        // u_status on ALL FOUR module case tables -- clearance_case, risk_case,
        // exposure_case and quote_and_bind_case share one status list: how far
        // that module's work has got. Distinct from activity_status (WHICH step
        // the case is on) and from the base task `state` (the task lifecycle).
        U_STATUS: {
            PENDING:     SHARED.PENDING,
            IN_PROGRESS: SHARED.IN_PROGRESS,
            COMPLETE:    'complete',
            BLOCKED:     'blocked',
            DECLINED:    SHARED.DECLINED
        },

        // x_gegis_ins_policy_intake_case.direction
        DIRECTION: {
            INBOUND:  'inbound',
            OUTBOUND: 'outbound'
        },

        // x_gegis_ins_policy_extraction.extraction_status -- consumer / HITL
        // status: what the end user is doing with the extracted data.
        EXTRACTION_STATUS: {
            STARTED:        'started',
            PENDING:        SHARED.PENDING,
            EXTRACTED:      SHARED.EXTRACTED,
            PENDING_REVIEW: 'pending_review',
            REVIEWED:       'reviewed',
            APPLIED:        SHARED.APPLIED,
            ACCEPTED:       SHARED.ACCEPTED,
            REJECTED:       SHARED.REJECTED,
            FAILED:         SHARED.FAILED
        },

        // x_gegis_ins_policy_extraction.extraction_method -- the technique /
        // engine that produced the extraction (AI provenance for HITL).
        EXTRACTION_METHOD: {
            OCR:            'ocr',
            AZURE_DI:       'azure_di',
            AZ_CU:          'az_cu',
            LLM_EXTRACTION: 'llm_extraction',
            HYBRID:         'hybrid',
            MANUAL:         'manual'
        },

        // x_gegis_ins_policy_extraction.disposition -- AI / system status:
        // what the pipeline did with the extraction record.
        DISPOSITION: {
            EXTRACTED:  SHARED.EXTRACTED,
            APPLIED:    SHARED.APPLIED,
            MERGED:     'merged',
            SUPERSEDED: 'superseded'
        },

        // x_gegis_ins_policy_extraction.source -- origination channel of the
        // extracted document/data (feeds submission.source_channel).
        SOURCE: {
            EMAIL:  'email',
            FILE:   'file',
            CASE:   SHARED.CASE,
            API:    'api',
            PORTAL: 'portal'
        },

        // x_gegis_ins_policy_party.party_type -- an organisation or an individual.
        // Values were originally UPPERCASE ('COMPANY'/'PERSON'); converted to
        // lower_snake_case by add_party_type_choices.js so party_type matches
        // every other custom choice in the app. The dictionary default moved
        // from 'COMPANY' to 'company' at the same time.
        PARTY_TYPE: {
            COMPANY: 'company',
            PERSON:  'person'
        },

        // x_gegis_ins_policy_party.status -- lifecycle of the party registry
        // entry itself, NOT the status of any submission or policy the party
        // appears on. A prospect has been captured but not yet transacted with.
        PARTY_STATUS: {
            ACTIVE:   SHARED.ACTIVE,
            INACTIVE: 'inactive',
            PROSPECT: 'prospect'
        },

        // x_gegis_ins_policy_submission_party.role -- WHAT a party is on the deal.
        // Roles live on the relationship, never on the party itself, so the same
        // registry entry can be the insured on one submission and an interest
        // holder on another.
        //
        // DELIBERATELY NON-OVERLAPPING with its two sibling columns:
        //   interest_type            holds the KIND of financial interest, so
        //                            'mortgagee' / 'loss_payee' / 'lienholder' are
        //                            NOT roles - use role = interest_holder and put
        //                            the kind in interest_type.
        //   relationship_to_primary  holds the corporate relationship, so
        //                            'parent' / 'subsidiary' / 'affiliate' are NOT
        //                            roles either.
        // One fact, one column.
        SUBMISSION_PARTY_ROLE: {
            PRIMARY_INSURED:    'primary_insured',
            CO_APPLICANT:       'co_applicant',
            SECONDARY_INSURED:  'secondary_insured',
            ADDITIONAL_INSURED: 'additional_insured',
            INTEREST_HOLDER:    'interest_holder',
            BROKER:             'broker',
            PRODUCER:           'producer',
            PREMIUM_PAYER:      'premium_payer',
            THIRD_PARTY:        'third_party'
        },

        // x_gegis_ins_policy_submission_party.interest_type -- the KIND of
        // financial stake a party holds in the risk. Only meaningful when
        // role = interest_holder; that pairing is what makes loan_number and
        // interest_address usable.
        //
        //   mortgagee          lender secured on insured REAL property. Mortgagee
        //                      clause, named on the loss draft, gets cancellation
        //                      notice. Needs loan_number + interest_address.
        //   loss_payee         paid from claim proceeds ahead of the insured,
        //                      typically financed equipment or fleet. Loss payable
        //                      clause, joint claim settlement.
        //   lienholder         lien over a specific asset, usually a vehicle.
        //                      Shows per vehicle on the auto schedule.
        //   certificate_holder needs EVIDENCE of insurance only - no claim rights
        //                      and no notice obligation. Not the same as
        //                      ROLE.ADDITIONAL_INSURED, who actually has cover.
        //   additional_interest catch-all for any other recorded interest, so
        //                      nobody invents new values. No 'other' on purpose.
        INTEREST_TYPE: {
            MORTGAGEE:           'mortgagee',
            LOSS_PAYEE:          'loss_payee',
            LIENHOLDER:          'lienholder',
            CERTIFICATE_HOLDER:  'certificate_holder',
            ADDITIONAL_INTEREST: 'additional_interest'
        },

        // x_gegis_ins_policy_party.verification_source -- which external business
        // registry / data provider was used to verify this party. GLEIF is the
        // free LEI registry; the rest are commercial.
        VERIFICATION_SOURCE: {
            DNB:          'dnb',
            GLEIF:        'gleif',
            LEXISNEXIS:   'lexisnexis',
            MOODYS_ORBIS: 'moodys_orbis',
            MIDDESK:      'middesk',
            OTHER:        SHARED.OTHER
        },

        // x_gegis_ins_policy_renewal_case.uw_decision -- underwriter's renewal
        // decision (human). Same value set as system_decision (see SHARED).
        UW_DECISION: {
            FULL_RE_UNDERWRITING: SHARED.FULL_RE_UNDERWRITING,
            AUTO_RENEW:           SHARED.AUTO_RENEW,
            DO_NOT_RENEW:         SHARED.DO_NOT_RENEW
        },

        // x_gegis_ins_policy_renewal_case.system_decision -- rule-engine /
        // automated renewal decision. Same value set as uw_decision.
        SYSTEM_DECISION: {
            FULL_RE_UNDERWRITING: SHARED.FULL_RE_UNDERWRITING,
            AUTO_RENEW:           SHARED.AUTO_RENEW,
            DO_NOT_RENEW:         SHARED.DO_NOT_RENEW
        },

        // x_gegis_ins_policy_renewal_case.notification_mode -- how the renewal
        // reminder is delivered.
        NOTIFICATION_MODE: {
            EMAIL:  'email',
            SMS:    'sms',
            OTHERS: 'others'
        },

        SUBMISSION_TYPE: {
            NEW_BUSINESS:  SHARED.NEW_BUSINESS,
            RENEWAL:       SHARED.RENEWAL,
            ENDORSEMENT:   'endorsement',
            CANCELLATION:  'cancellation',
            REINSTATEMENT: 'reinstatement'
        },

        // line_of_business on policy, product, quote_option, existing_policy,
        // exposure_item, rate_table and rate_factor. The last two carried this as
        // `lob` until the column was dropped and re-added under the proper name -
        // one taxonomy, one column name, everywhere.
        // MOTOR and WORKERS_COMP were live on the tables before
        // they were catalogued here, so the list was reconciled upwards rather
        // than deleting values in use. MOTOR is not a duplicate of AUTO: auto is
        // the US personal/commercial auto line, motor the non-US equivalent, and
        // both appear on Product.
        //
        // NOT the same list as submission_line / extraction_mapping, which carry
        // a broker-facing taxonomy (general_liability, inland_marine, umbrella,
        // plus an 'all' sentinel on the mapping table). Those stay separate on
        // purpose - merging them is a data-model decision, not a cleanup.
        LINE_OF_BUSINESS: {
            PROPERTY:        'property',
            AUTO:            'auto',
            MOTOR:           'motor',
            WORKERS_COMP:    'workers_comp',
            GENERAL:         'general',
            CASUALTY:        'casualty',
            MARINE:          'marine',
            ENERGY:          'energy',
            FINANCIAL_LINES: 'financial_lines',
            CONSTRUCTION:    'construction',
            AVIATION:        'aviation',
            CYBER:           'cyber',
            SPECIALTY:       'specialty'
        },

        // currency on policy, quote, submission and exposure_item. ISO 4217
        // alpha-3, stored lower_snake_case like every other choice; the LABEL is
        // the uppercase code. Column is max_length 3.
        CURRENCY: {
            USD: 'usd',
            GBP: 'gbp',
            EUR: 'eur',
            CAD: 'cad',
            AUD: 'aud',
            JPY: 'jpy',
            CHF: 'chf'
        },

        // x_gegis_ins_policy_policy.territory -- underwriting territory the risk
        // sits in. GLOBAL is a real selection (worldwide cover), not a wildcard.
        TERRITORY: {
            US:     'us',
            UK:     'uk',
            EU:     'eu',
            APAC:   'apac',
            GLOBAL: 'global'
        },

        // =================================================================
        // PRODUCT CATALOG
        // =================================================================

        // product.status and coverage.status -- AUTHORING lifecycle of the
        // definition. Nothing to do with a policy being live: see POLICY_STATUS
        // for that. A published product is sellable; archived is withdrawn but
        // still referenced by policies already written on it.
        CATALOG_STATUS: {
            DRAFT:     SHARED.DRAFT,
            PUBLISHED: 'published',
            ARCHIVED:  'archived'
        },

        // coverage.coverage_selection and coverage_category.coverage_selection --
        // whether the coverage must be taken on this product.
        COVERAGE_SELECTION: {
            REQUIRED: 'required',
            OPTIONAL: 'optional',
            EXCLUDED: SHARED.EXCLUDED
        },

        // coverage.cause_of_loss_form -- breadth of perils on a property form,
        // narrowest to widest. SPECIAL is open-perils (all but what is excluded).
        CAUSE_OF_LOSS_FORM: {
            BASIC:        'basic',
            BROAD:        'broad',
            SPECIAL:      'special',
            NAMED_PERILS: 'named_perils'
        },

        // coverage.deductible_type -- how the deductible is expressed and what it
        // attaches to.
        DEDUCTIBLE_TYPE: {
            FLAT:           SHARED.FLAT,
            PERCENTAGE:     SHARED.PERCENTAGE,
            PER_OCCURRENCE: SHARED.PER_OCCURRENCE,
            PER_LOCATION:   SHARED.PER_LOCATION,
            WAITING_PERIOD: SHARED.WAITING_PERIOD
        },

        // coverage.limit_type -- the basis the limit attaches to.
        LIMIT_TYPE: {
            PER_OCCURRENCE:        SHARED.PER_OCCURRENCE,
            PER_LOCATION:          SHARED.PER_LOCATION,
            AGGREGATE:             'aggregate',
            PER_ITEM:              'per_item',
            COMBINED_SINGLE_LIMIT: 'combined_single_limit'
        },

        // coverage.valuation_basis -- how a loss is valued at settlement.
        VALUATION_BASIS: {
            RCV:                    'rcv',
            ACV:                    'acv',
            AGREED_VALUE:           'agreed_value',
            FUNCTIONAL_REPLACEMENT: 'functional_replacement'
        },

        // coverage_term.term_type -- the PRODUCT CATALOG side. Prices and shapes
        // a term before anything is sold, so PREMIUM and FEE live here.
        // Deliberately a different set from POLICY_TERM_TYPE despite the shared
        // column name: same name, different domain.
        TERM_TYPE: {
            LIMIT:      SHARED.LIMIT,
            DEDUCTIBLE: SHARED.DEDUCTIBLE,
            DURATION:   SHARED.DURATION,
            PREMIUM:    'premium',
            PERCENTAGE: SHARED.PERCENTAGE,
            FEE:        'fee'
        },

        // policy_coverage_term.term_type -- the ISSUED POLICY side. Records the
        // shape of cover actually granted, so SUBLIMIT and COINSURANCE live here.
        POLICY_TERM_TYPE: {
            LIMIT:          SHARED.LIMIT,
            DEDUCTIBLE:     SHARED.DEDUCTIBLE,
            SUBLIMIT:       'sublimit',
            WAITING_PERIOD: SHARED.WAITING_PERIOD,
            COINSURANCE:    'coinsurance'
        },

        // coverage_term.data_type -- how a term's VALUE is stored and rendered.
        // CURRENCY here is a DATA TYPE, not a currency code; it is deliberately
        // not shared with CHOICE.CURRENCY, which holds usd/gbp/...
        TERM_DATA_TYPE: {
            CURRENCY:   'currency',
            PERCENTAGE: SHARED.PERCENTAGE,
            INTEGER:    'integer',
            TEXT:       'text',
            DATE:       'date',
            DURATION:   SHARED.DURATION
        },

        // policy_coverage.status -- a strict subset of POLICY_STATUS. A coverage
        // line is only ever running, killed mid-term, or lapsed at expiry.
        POLICY_COVERAGE_STATUS: {
            ACTIVE:    SHARED.ACTIVE,
            CANCELLED: SHARED.CANCELLED,
            EXPIRED:   SHARED.EXPIRED
        },

        // major_exclusion.exclusion_type -- the market-standard major exclusions
        // an underwriter must positively address on every submission.
        EXCLUSION_TYPE: {
            AFFIRMATIVE_CYBER:         'affirmative_cyber',
            NUCLEAR:                   'nuclear',
            RADIOACTIVE_CONTAMINATION: 'radioactive_contamination',
            WAR_CIVIL_WAR:             'war_civil_war',
            COMMUNICABLE_DISEASE:      'communicable_disease',
            OTHER:                     SHARED.OTHER
        },

        // major_exclusion.choice_value -- how that exclusion was actually treated
        // on this deal. SUB_LIMITED is the middle ground: covered, but capped.
        EXCLUSION_TREATMENT: {
            INCLUDED:    SHARED.INCLUDED,
            EXCLUDED:    SHARED.EXCLUDED,
            SUB_LIMITED: 'sub_limited'
        },

        // =================================================================
        // RATING
        // =================================================================

        // rate_table.rate_type -- the unit a rate is quoted in.
        RATE_TYPE: {
            PER_MILLE:  'per_mille',
            PERCENTAGE: SHARED.PERCENTAGE,
            FLAT:       SHARED.FLAT
        },

        // rate_factor.factor_type -- direction the factor moves premium.
        FACTOR_TYPE: {
            DISCOUNT:   'discount',
            LOADING:    'loading',
            MULTIPLIER: 'multiplier'
        },

        // rate_factor.applies_to -- level the factor bites at.
        FACTOR_APPLIES_TO: {
            POLICY:   'policy',
            RISK:     'risk',
            COVERAGE: 'coverage'
        },

        // rate_table_entry.zone -- motor rating territory. ANY is a WILDCARD row
        // meaning the rate applies regardless of zone, not a real zone.
        ZONE: {
            METRO: 'metro',
            URBAN: 'urban',
            RURAL: 'rural',
            ANY:   SHARED.ANY
        },

        // rate_table_entry.vehicle_type -- motor RATING classes. Deliberately NOT
        // the same list as vehicle.vehicle_type, which classifies the physical
        // vehicle (private_passenger, light_truck, ...). Same column name, two
        // different questions: how it rates vs what it is.
        RATING_VEHICLE_TYPE: {
            PRIVATE_CAR: 'private_car',
            TWO_WHEELER: 'two_wheeler',
            COMMERCIAL:  SHARED.COMMERCIAL,
            TAXI:        'taxi'
        },

        // rate_table_entry.engine_cc -- motor rating band. ANY is the same
        // wildcard as ZONE.ANY.
        ENGINE_CC: {
            UPTO_350CC:   'upto_350cc',
            UPTO_1500CC:  'upto_1500cc',
            ABOVE_1500CC: 'above_1500cc',
            ANY:          SHARED.ANY
        },

        // =================================================================
        // RISK -- the columns rating MATCHES ON. policy_risk, quote_risk and
        // rate_table_entry must stay byte-identical here or premium lookup
        // silently misses and quotes come back empty.
        // =================================================================

        // ISO construction class. ALSO location.construction_type, which used to
        // carry 'masonry_non_comb' where the rating tables carry 'masonry' - that
        // mismatch broke the join and is retired by
        // add_product_rating_choices.js.
        CONSTRUCTION: {
            FIRE_RESISTIVE:          'fire_resistive',
            MODIFIED_FIRE_RESISTIVE: 'modified_fire_resistive',
            MASONRY:                 'masonry',
            JOISTED_MASONRY:         'joisted_masonry',
            NON_COMBUSTIBLE:         'non_combustible',
            FRAME:                   'frame'
        },

        OCCUPANCY: {
            RETAIL_MALL:   'retail_mall',
            WAREHOUSE:     'warehouse',
            OFFICE:        'office',
            IT_OFFICE:     'it_office',
            MANUFACTURING: 'manufacturing',
            RESTAURANT:    'restaurant',
            HEALTHCARE:    'healthcare',
            EDUCATION:     'education',
            HOSPITALITY:   'hospitality'
        },

        PROTECTION: {
            SPRINKLERED:       'sprinklered',
            NO_SPRINKLER:      'no_sprinkler',
            PARTIAL_SPRINKLER: 'partial_sprinkler',
            FIRE_ALARM_ONLY:   'fire_alarm_only',
            FULL_SUPPRESSION:  'full_suppression'
        },

        // policy_risk.exposure / quote_risk.exposure -- the surroundings of the
        // risk. Named RISK_EXPOSURE here so it is never confused with the
        // exposure-management module or with exposure_item.
        RISK_EXPOSURE: {
            URBAN_LOW:       'urban_low',
            SUBURBAN_MEDIUM: 'suburban_medium',
            INDUSTRIAL_HIGH: 'industrial_high',
            RURAL_LOW:       'rural_low',
            COASTAL:         'coastal',
            FLOOD_ZONE:      'flood_zone'
        },

        // policy_risk.risk_type / quote_risk.risk_type -- what the risk line
        // actually covers.
        RISK_TYPE: {
            BUILDING:              'building',
            CONTENTS:              'contents',
            BUSINESS_INTERRUPTION: 'business_interruption',
            VEHICLE:               'vehicle',
            EQUIPMENT:             'equipment'
        },

        // =================================================================
        // LETTER OF AUTHORITY  (loa_* tables)
        // -----------------------------------------------------------------
        // The LOA subsystem is deliberately DATA-driven: a new LOB or a new
        // metric is rows in loa_metric + loa_authority_limit, never a new column
        // and never a new value here. These lists describe the SHAPE of a limit,
        // not the limits themselves.
        //
        // Two things are reused rather than redefined and must stay that way:
        //   line_of_business -> CHOICE.LINE_OF_BUSINESS  (above)
        //   currency         -> CHOICE.CURRENCY          (above)
        // A second LOA-only LOB list is exactly the GL / GENERAL_LIABILITY drift
        // this model exists to remove.
        // =================================================================

        // loa_authority_tier.code is a STRING with a unique index, not a choice -
        // adding Tier 6 must be one row, not an edit in five places. The known
        // codes are named here so scripts and seeds never type 'tier_3' raw.
        LOA_TIER: {
            TIER_1: 'tier_1',
            TIER_2: 'tier_2',
            TIER_3: 'tier_3',
            TIER_4: 'tier_4',
            TIER_5: 'tier_5'
        },

        // loa_metric.value_type -- which of limit_amount / limit_count /
        // limit_percent a limit row on this metric is expected to populate.
        LOA_METRIC_VALUE_TYPE: {
            AMOUNT:  'amount',
            COUNT:   SHARED.COUNT,
            PERCENT: 'percent'
        },

        // loa_metric.comparison -- the DIRECTION of a breach, held as data instead
        // of being implied by a column name. MIN is not an edge case: deductible
        // floors and minimum-premium rules breach when the actual value is BELOW
        // the limit, and getting that backwards silently authorises bad risk.
        LOA_METRIC_COMPARISON: {
            MAX: SHARED.MAX,
            MIN: 'min'
        },

        // loa_metric.source_anchor -- WHAT the source rows hang off, and therefore
        // whether the metric can be checked at all on a given evaluation.
        //   submission_line  readable from intake onwards
        //   quote_option     readable only once a quote exists
        // Per-occurrence limits and deductibles are QUOTE attributes: at
        // submission stage there is nothing to check, and the honest answer is
        // not_applicable, not "within authority". Without this the resolver has
        // to guess from the source table's shape.
        LOA_METRIC_SOURCE_ANCHOR: {
            SUBMISSION_LINE: 'submission_line',
            QUOTE_OPTION:    'quote_option'
        },

        // loa_metric.aggregation -- how child rows roll up into one exposure
        // figure. Child rows are found by the anchor reference above.
        LOA_METRIC_AGGREGATION: {
            NONE:  SHARED.NONE,
            SUM:   'sum',
            MAX:   SHARED.MAX,
            COUNT: SHARED.COUNT
        },

        // loa_metric.peril -- cat perils a limit can be cut by. NOT yet applied to
        // exposure_peril.peril, which carries an older uncatalogued list; see the
        // note at the bottom of this block.
        PERIL: {
            WIND:      'wind',
            QUAKE:     'quake',
            FLOOD:     'flood',
            HAIL:      'hail',
            WILDFIRE:  'wildfire',
            TERRORISM: 'terrorism',
            ALL_OTHER: 'all_other'
        },

        // loa_jurisdiction.region -- grouping over jurisdictions, so a whole
        // region can be granted in one action and reported on as one.
        LOA_REGION: {
            US_WEST:    'us_west',
            US_EAST:    'us_east',
            US_CENTRAL: 'us_central',
            US_SOUTH:   'us_south',
            NON_US:     'non_us'
        },

        // loa_authority_limit.operator -- how exposure is compared with the limit.
        LOA_OPERATOR: {
            LTE: 'lte',
            GTE: 'gte',
            EQ:  'eq'
        },

        // loa_authority_limit.class_of_business -- occupancy class the limit is cut
        // by. ALL is a WILDCARD row (applies regardless of class), not a real class.
        CLASS_OF_BUSINESS: {
            ALL:           SHARED.ALL,
            OFFICE:        'office',
            RETAIL:        'retail',
            MANUFACTURING: 'manufacturing',
            WAREHOUSE:     'warehouse',
            PETROCHEMICAL: 'petrochemical',
            HOSPITALITY:   'hospitality',
            HEALTHCARE:    'healthcare',
            EDUCATION:     'education',
            MUNICIPAL:     'municipal',
            HABITATIONAL:  'habitational'
        },

        // loa_authority_limit.business_type -- new business vs renewal authority.
        // Same tokens as SUBMISSION_TYPE plus the ALL wildcard; deliberately a
        // separate group because it also answers "or both", which a submission
        // type never does.
        LOA_BUSINESS_TYPE: {
            ALL:          SHARED.ALL,
            NEW_BUSINESS: SHARED.NEW_BUSINESS,
            RENEWAL:      SHARED.RENEWAL
        },

        // loa_authority_limit.bind_authority -- what the holder may actually DO
        // once inside the limit. QUOTE_ONLY is the carve-out that lets a class be
        // quoted at a tier but never bound there.
        LOA_BIND_AUTHORITY: {
            QUOTE_AND_BIND: 'quote_and_bind',
            QUOTE_ONLY:     'quote_only',
            REFER_ONLY:     'refer_only'
        },

        // loa_authority_grant.grantee_type -- ROLE is the standing grant and needs
        // no maintenance when a person joins, moves or leaves. USER is the named
        // exception, normally a delegation.
        LOA_GRANTEE_TYPE: {
            ROLE: 'role',
            USER: 'user'
        },

        // loa_authority_grant.state -- the ONLY lifecycle field on a grant. There
        // is deliberately no `active` boolean beside it: two fields that can
        // disagree about whether authority is live is a bug waiting to happen.
        LOA_GRANT_STATE: {
            DRAFT:      SHARED.DRAFT,
            ACTIVE:     SHARED.ACTIVE,
            SUPERSEDED: SHARED.SUPERSEDED,
            REVOKED:    SHARED.REVOKED,
            EXPIRED:    SHARED.EXPIRED
        },

        // loa_evaluation.evaluation_trigger -- why this VERSION of the evaluation
        // exists. Evaluations are never updated in place; a change writes a new
        // version and deactivates the last.
        LOA_EVALUATION_TRIGGER: {
            INITIAL_EVALUATION:  'initial_evaluation',
            INTAKE_CHANGE:       'intake_change',
            EXPOSURE_CHANGE:     'exposure_change',
            GRANT_CHANGE:        'grant_change',
            QUOTE_CHANGE:        'quote_change',
            MANUAL_REEVALUATION: 'manual_reevaluation'
        },

        // loa_evaluation.evaluation_status -- the decision. NO_AUTHORITY means no
        // grant matched at all, which is a different problem from a breach and
        // must never be reported as one: a breach means the underwriter is over
        // their limit, no_authority means they have no limit on this LOB.
        LOA_EVALUATION_STATUS: {
            PENDING:                           SHARED.PENDING,
            AUTHORIZED:                        'authorized',
            BREACH:                            'breach',
            // 'referred' (the decision), NOT SHARED.REFERRAL ('referral', the
            // case_task category). Two different words for two different things.
            REFERRED:                          'referred',
            REFERRED_APPROVED:                 'referred_approved',
            REFERRED_APPROVED_WITH_CONDITIONS: 'referred_approved_with_conditions',
            REFERRED_REJECTED:                 'referred_rejected',
            REFERRED_REJECTED_ALTERNATE_TERMS: 'referred_rejected_alternate_terms',
            DECLINED:                          SHARED.DECLINED,
            NO_AUTHORITY:                      'no_authority'
        },

        // loa_evaluation_line.result -- the per-metric outcome. NO_LIMIT means the
        // tier has no limit row for that metric, which is NOT the same as being
        // within one; reporting it as WITHIN would hide a gap in the grid.
        LOA_LINE_RESULT: {
            WITHIN:         'within',
            BREACH:         'breach',
            NOT_APPLICABLE: 'not_applicable',
            NO_LIMIT:       'no_limit'
        }

        // OPEN ITEM: exposure_peril.peril carries an uncatalogued list that predates
        // CHOICE.PERIL above. Reconciling the two is a data decision (it would
        // rewrite live exposure_peril rows), not a cleanup - leave both until it is
        // taken deliberately.
    };

    // Collect the value strings of a choice group as an array (for IN queries,
    // validation, etc.). Skips function members such as ACTIVITY.all.
    function values(map) {
        var out = [];
        for (var k in map) {
            if (map.hasOwnProperty(k) && typeof map[k] === 'string')
                out.push(map[k]);
        }
        return out;
    }

    // ---------------------------------------------------------------------
    // Generic typed getters. dflt is optional; when omitted the registered
    // DEFAULT for that property (or a safe empty/false) is used.
    // ---------------------------------------------------------------------
    function getString(name, dflt) {
        var d = (dflt !== undefined) ? dflt : (DEFAULT[name] !== undefined ? DEFAULT[name] : '');
        return gs.getProperty(name, d);
    }

    function getBool(name, dflt) {
        var d = (dflt !== undefined) ? (dflt ? 'true' : 'false')
                                     : (DEFAULT[name] !== undefined ? DEFAULT[name] : 'false');
        return getString(name, d) === 'true';
    }

    // Parse a JSON-valued property. Returns the parsed object, or dflt
    // (default {}) when the property is empty or not valid JSON.
    function getJson(name, dflt) {
        var fallback = (dflt !== undefined) ? dflt : {};
        var raw = getString(name, '');
        if (!raw)
            return fallback;
        try {
            var parsed = JSON.parse(raw);
            return (parsed && typeof parsed === 'object') ? parsed : fallback;
        } catch (e) {
            gs.warn('[Constants] property ' + name + ' is not valid JSON: ' + e.message);
            return fallback;
        }
    }

    // ---------------------------------------------------------------------
    // Domain helpers.
    // ---------------------------------------------------------------------
    // intent: 'new' (POST /submission) | 'update' (PUT /submission/{number}).
    // Returns true when that intent's extraction should be auto-approved.
    function isAutoApprove(intent) {
        return (String(intent) === 'update')
            ? getBool(PROP.AUTO_APPROVE_UPDATE)
            : getBool(PROP.AUTO_APPROVE_NEW);
    }

    // Parsed license + staged execution plan. Empty object if unset/invalid.
    function getModuleExecutionConfig() {
        return getJson(PROP.MODULE_EXECUTION_CONFIG, {});
    }

    return {
        SCOPE: SCOPE,
        PROP: PROP,
        CHOICE: CHOICE,
        values: values,
        getString: getString,
        getBool: getBool,
        getJson: getJson,
        isAutoApprove: isAutoApprove,
        getModuleExecutionConfig: getModuleExecutionConfig
    };
})();
